import{_ as o,C as r,c as i,o as n,a6 as e,G as d}from"./chunks/framework.BY05barL.js";const b=JSON.parse('{"title":"Algoritmos de Reemplazo de Páginas","description":"","frontmatter":{},"headers":[],"relativePath":"unidad3/algoritmos-reemplazo.md","filePath":"unidad3/algoritmos-reemplazo.md"}'),l={name:"unidad3/algoritmos-reemplazo.md"};function s(p,a,c,m,g,u){const t=r("PageReplacementVictim");return n(),i("div",null,[a[0]||(a[0]=e('<h1 id="algoritmos-de-reemplazo-de-paginas" tabindex="-1">Algoritmos de Reemplazo de Páginas <a class="header-anchor" href="#algoritmos-de-reemplazo-de-paginas" aria-label="Permalink to &quot;Algoritmos de Reemplazo de Páginas&quot;">​</a></h1><p>Cuando ocurre un fallo de página y no hay marcos libres en memoria, el sistema operativo debe seleccionar una página para desalojar. Los algoritmos de reemplazo determinan qué página debe ser reemplazada.</p><h2 id="objetivo" tabindex="-1">Objetivo <a class="header-anchor" href="#objetivo" aria-label="Permalink to &quot;Objetivo&quot;">​</a></h2><p>Minimizar la <strong>tasa de fallos de página</strong> seleccionando la página que tiene menor probabilidad de ser usada en el futuro cercano.</p><h2 id="algoritmos-principales" tabindex="-1">Algoritmos Principales <a class="header-anchor" href="#algoritmos-principales" aria-label="Permalink to &quot;Algoritmos Principales&quot;">​</a></h2><h3 id="_1-optimo-de-referencia" tabindex="-1">1. Óptimo (de referencia) <a class="header-anchor" href="#_1-optimo-de-referencia" aria-label="Permalink to &quot;1. Óptimo (de referencia)&quot;">​</a></h3><p><strong>Estrategia:</strong> Reemplazar la página que se va a usar más lejos en el futuro. Da la menor cantidad de fallos posible, pero no se puede implementar (el SO no conoce las referencias futuras): se usa como referencia para comparar los demás.</p><h3 id="_2-fifo-first-in-first-out" tabindex="-1">2. FIFO (First-In, First-Out) <a class="header-anchor" href="#_2-fifo-first-in-first-out" aria-label="Permalink to &quot;2. FIFO (First-In, First-Out)&quot;">​</a></h3><p><strong>Estrategia:</strong> Reemplazar la página que lleva más tiempo en memoria (la más antigua).</p><p><strong>Implementación:</strong></p><ul><li>Cola circular</li><li>Al cargar una página, se añade al final de la cola</li><li>Al reemplazar, se elimina del frente de la cola</li></ul><p><strong>Ventajas:</strong></p><ul><li>Muy simple de implementar</li><li>Bajo overhead</li></ul><p><strong>Desventajas:</strong></p><ul><li>No considera el uso real de las páginas</li><li>Puede reemplazar páginas muy usadas</li><li>Sufre la <strong>anomalía de Belady</strong>: con más marcos puede haber más fallos, porque FIFO no es un algoritmo de pila (las páginas en memoria con n marcos no siempre están entre las que habría con n + 1)</li><li>Ejemplo clásico: la cadena 0 1 2 3 0 1 4 0 1 2 3 4 produce 9 fallos con 3 marcos y 10 con 4</li></ul><h3 id="_3-lru-least-recently-used" tabindex="-1">3. LRU (Least Recently Used) <a class="header-anchor" href="#_3-lru-least-recently-used" aria-label="Permalink to &quot;3. LRU (Least Recently Used)&quot;">​</a></h3><p><strong>Estrategia:</strong> Reemplazar la página que no ha sido usada durante el período más largo.</p><p><strong>Principio de localidad:</strong> Las páginas usadas recientemente probablemente se usarán pronto.</p><p><strong>Implementación:</strong></p><ul><li><strong>Contador:</strong> Timestamp en cada acceso</li><li><strong>Pila:</strong> Mover página accedida al tope</li><li><strong>Matriz de bits:</strong> Actualizar matriz en cada acceso</li></ul><p><strong>Ventajas:</strong></p><ul><li>Buen rendimiento en la práctica</li><li>Aproxima bien el algoritmo óptimo</li><li>No sufre la anomalía de Belady (es un algoritmo de pila)</li></ul><p><strong>Desventajas:</strong></p><ul><li>Alto overhead por mantener tiempos de acceso</li><li>Puede ser costoso encontrar la página LRU</li></ul><h3 id="_4-segunda-oportunidad-clock-reloj" tabindex="-1">4. Segunda Oportunidad (Clock / Reloj) <a class="header-anchor" href="#_4-segunda-oportunidad-clock-reloj" aria-label="Permalink to &quot;4. Segunda Oportunidad (Clock / Reloj)&quot;">​</a></h3><p><strong>Estrategia:</strong> Aproximación eficiente de LRU usando el bit de referencia (R).</p><p><strong>Algoritmo:</strong></p><ol><li>Organizar marcos en lista circular (como un reloj)</li><li>Mantener puntero &quot;manecilla del reloj&quot;</li><li>Al necesitar reemplazo: <ul><li>Si R=0: reemplazar página</li><li>Si R=1: dar segunda oportunidad (R=0) y avanzar</li></ul></li></ol><p><strong>Ventajas:</strong></p><ul><li>Más eficiente que LRU (menor overhead)</li><li>Razonablemente efectivo</li><li>Usa hardware existente (bit R)</li></ul><p><strong>Desventajas:</strong></p><ul><li>Puede degenerar en FIFO si todas las páginas tienen R=1</li></ul><h3 id="_5-nru-not-recently-used" tabindex="-1">5. NRU (Not Recently Used) <a class="header-anchor" href="#_5-nru-not-recently-used" aria-label="Permalink to &quot;5. NRU (Not Recently Used)&quot;">​</a></h3><p><strong>Estrategia:</strong> Usar bits R (referencia) y M (modificación) para clasificar páginas en 4 clases.</p><p><strong>Clases (en orden de preferencia para reemplazo):</strong></p><table tabindex="0"><thead><tr><th>Clase</th><th>R</th><th>M</th><th>Descripción</th><th>Preferencia</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>0</td><td>No referenciada, no modificada</td><td>1ª (mejor)</td></tr><tr><td>1</td><td>0</td><td>1</td><td>No referenciada, modificada</td><td>2ª</td></tr><tr><td>2</td><td>1</td><td>0</td><td>Referenciada, no modificada</td><td>3ª</td></tr><tr><td>3</td><td>1</td><td>1</td><td>Referenciada, modificada</td><td>4ª (peor)</td></tr></tbody></table><p><strong>Algoritmo:</strong></p><ol><li>Periódicamente, el SO resetea los bits R de todas las páginas</li><li>Al necesitar reemplazo, seleccionar aleatoriamente una página de la clase más baja no vacía</li></ol><p><strong>Ventajas:</strong></p><ul><li>Simple de implementar</li><li>Distingue entre páginas modificadas y no modificadas</li><li>Evita escribir páginas no modificadas</li></ul><p><strong>Desventajas:</strong></p><ul><li>Menos preciso que LRU</li><li>Necesita los bits R y M; si el hardware no los tiene, el SO puede simularlos por software (con fallos de protección en el primer acceso)</li></ul><h2 id="ejercicio-8-reemplazo-de-paginas" tabindex="-1">Ejercicio 8: Reemplazo de Páginas <a class="header-anchor" href="#ejercicio-8-reemplazo-de-paginas" aria-label="Permalink to &quot;Ejercicio 8: Reemplazo de Páginas&quot;">​</a></h2><p>Dado un sistema con 5 marcos de página:</p><table tabindex="0"><thead><tr><th>Nº Página</th><th>Marco</th><th>¿En memoria?</th><th>Tiempo carga</th><th>Tiempo última ref</th><th>M</th><th>R</th></tr></thead><tbody><tr><td>0</td><td>3</td><td>Sí</td><td>3200</td><td>5600</td><td>1</td><td>1</td></tr><tr><td>1</td><td>0</td><td>Sí</td><td>2400</td><td>5440</td><td>1</td><td>1</td></tr><tr><td>2</td><td>-</td><td>No</td><td>0</td><td>0</td><td>0</td><td>0</td></tr><tr><td>3</td><td>2</td><td>Sí</td><td>2600</td><td>5200</td><td>0</td><td>1</td></tr><tr><td>4</td><td>4</td><td>Sí</td><td>2520</td><td>5580</td><td>0</td><td>0</td></tr></tbody></table><p><strong>a) ¿Qué página reemplaza NRU?</strong></p><p>La única página de la clase 0 (R=0, M=0) es la 4. <strong>Respuesta: página 4.</strong></p><p><strong>b) ¿Qué página reemplaza FIFO?</strong></p><p>La cargada hace más tiempo es la 1 (tiempo 2400). <strong>Respuesta: página 1.</strong></p><p><strong>c) ¿Qué página reemplaza LRU?</strong></p><p>La de última referencia más vieja es la 3 (tiempo 5200). <strong>Respuesta: página 3.</strong></p><p><strong>d) ¿Qué página reemplaza Segunda Oportunidad?</strong></p><p>La más antigua (1) tiene R=1: se le pone R=0 y pasa al final de la cola. La siguiente (4) tiene R=0. <strong>Respuesta: página 4.</strong></p><p><strong>e) ¿Hay inconsistencias?</strong></p><p><strong>Sí</strong>, dos:</p><ul><li><strong>Bit R de la página 4:</strong> fue referenciada en 5580, después que la 3 (5200) y la 1 (5440), pero es la única con R=0. Un reseteo periódico de R no lo explica, porque también habría puesto en 0 los bits R de las páginas 3 y 1.</li><li><strong>Marcos:</strong> hay 5 marcos pero solo se usan 4 (0, 2, 3 y 4); el marco 1 está libre. Un fallo de página cargaría la página en ese marco sin reemplazar ninguna.</li></ul><h3 id="simulador" tabindex="-1">Simulador <a class="header-anchor" href="#simulador" aria-label="Permalink to &quot;Simulador&quot;">​</a></h3><p>Tocá cada algoritmo para ver cómo ordena las páginas y cuál elige como víctima. También podés cambiar los bits R y M.</p>',58)),d(t),a[1]||(a[1]=e('<h2 id="comparacion-de-algoritmos" tabindex="-1">Comparación de Algoritmos <a class="header-anchor" href="#comparacion-de-algoritmos" aria-label="Permalink to &quot;Comparación de Algoritmos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Algoritmo</th><th>Complejidad</th><th>Overhead</th><th>Rendimiento</th><th>Notas</th></tr></thead><tbody><tr><td>Óptimo</td><td>-</td><td>-</td><td>El mejor</td><td>No implementable</td></tr><tr><td>FIFO</td><td>Baja</td><td>Muy bajo</td><td>Pobre</td><td>Anomalía de Belady</td></tr><tr><td>LRU</td><td>Alta</td><td>Alto</td><td>Muy bueno</td><td>Costoso mantener</td></tr><tr><td>Segunda Oportunidad</td><td>Media</td><td>Bajo</td><td>Bueno</td><td>Balance costo/beneficio</td></tr><tr><td>NRU</td><td>Baja</td><td>Bajo</td><td>Aceptable</td><td>Simple y efectivo</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><ul><li><strong>Para implementación práctica:</strong> Segunda Oportunidad o NRU</li><li><strong>Si hay recursos:</strong> LRU (mejor rendimiento)</li><li><strong>Si simplicidad es crítica:</strong> FIFO (pero con cuidado)</li></ul>',4))])}const f=o(l,[["render",s]]);export{b as __pageData,f as default};
